from griffe.extensions import Extension
import griffe

class CheckedExtension(Extension):
    """Extension that appends ' [checked]' to all function docstrings."""

    def on_collect_function(self, func):
        """Append ' [checked]' to the function's docstring."""
        if func.docstring is not None:
            func.docstring.value += " [checked]"

# Load the package with the extension enabled
package = griffe.load("mypkg", extensions=[CheckedExtension()])

# Print sample results to verify the extension worked
for member in package.members.values():
    if hasattr(member, 'docstring') and member.docstring:
        print(f"{member.name}: {member.docstring.value}")
